import * as combobox from "@zag-js/combobox";
import type { MachineInput } from "marko-zag";
import { positionerStyle } from "marko-zag";
import Icon from "../icon/icon.marko";
import { cn } from "../../../lib/utils.ts";
import { stripOwnProps } from "../../../lib/native-attrs.ts";

export interface ComboboxItem {
  value: string;
  label: string;
  disabled?: boolean;
}

// Optional grouping — same display-only shape as select.marko's `groups`
// (zag has no native group concept; see combobox.props.mjs). Mirrors
// upstream's `ComboboxGroup`/`ComboboxLabel` slots.
export interface ComboboxGroupData {
  label: string;
  items: ComboboxItem[];
}

// `items`/`value` are narrowed vs. the raw machine Props: `items` drives the
// generated `collection`, and `value` is typed as the plain string[] the
// caller works with (the machine's own `value` type matches already).
export type Input = Omit<MachineInput<"div", combobox.Props>, "collection"> & {
  items: ComboboxItem[];
  groups?: ComboboxGroupData[];
  valueChange?: (value: string[]) => void;
  inputValueChange?: (inputValue: string) => void;
  highlightChange?: (highlightedValue: string | null) => void;
  /** Show the clear ("x") button when a value is selected. */
  showClear?: boolean;
};

<const/{ items, groups, showClear, class: className }=input/>

<let/filtered=items/>

<const/buildCollection=(list: ComboboxItem[]) =>
  combobox.collection({
    items: list,
    itemToValue: (item: ComboboxItem) => item.value,
    itemToString: (item: ComboboxItem) => item.label,
    isItemDisabled: (item: ComboboxItem) => !!item.disabled,
  })
/>

<machine-props/machineProps from=input pick=combobox.props
  onInputValueChange(details: combobox.InputValueChangeDetails) {
    input.onInputValueChange?.(details);
    input.inputValueChange?.(details.inputValue);
    // Only narrow the list while the user is typing. Zag also fires this
    // with reason "item-select" (writing the chosen label into the input),
    // which would otherwise re-filter the list down to the selection and
    // leave the reopened dropdown showing a single item.
    if (details.reason !== "input-change") {
      filtered = items;
      return;
    }
    const query = details.inputValue.trim().toLowerCase();
    filtered = query === "" ? items : items.filter((item) => item.label.toLowerCase().includes(query));
  }
  onValueChange(details: combobox.ValueChangeDetails) {
    input.onValueChange?.(details);
    input.valueChange?.(details.value);
    filtered = items;
  }
  onHighlightChange(details: combobox.HighlightChangeDetails) {
    input.onHighlightChange?.(details);
    input.highlightChange?.(details.highlightedValue);
  }/>
// `collection` is derived state (rebuilt whenever `filtered` changes), not a
// plain input field, so it cannot be picked/overridden inside <machine-props>
// (that tag's overrides are evaluated eagerly at the tag-input boundary).
// Wrap machineProps in a closure that layers it in for <service>.
<const/serviceProps=() => ({ ...machineProps(), collection: buildCollection(filtered) })/>
<service/service machine=() => combobox.machine props=serviceProps/>
<connect/api=(service, normalizeProps) =>
  combobox.connect(service, normalizeProps)
  service=service
/>

<const/nativeAttrs=() =>
  stripOwnProps(
    combobox.splitProps(input)[1],
    "class",
    "items",
    "groups",
    "valueChange",
    "inputValueChange",
    "highlightChange",
    "showClear",
  )
>

// `filteredGroups`: group shape re-derived from `filtered` so typing narrows
// each group's items the same way the flat list narrows (group membership by
// value lookup against the original `groups` prop).
<const/filteredGroups=() => {
  if (!groups) return null;
  const filteredValues = new Set(filtered.map((item) => item.value));
  return groups
    .map((group) => ({ label: group.label, items: group.items.filter((item) => filteredValues.has(item.value)) }))
    .filter((group) => group.items.length > 0);
}>

<div ...nativeAttrs() ...api().getRootProps() data-slot="combobox" class=cn(className)>
  <span data-slot="combobox-value" class="sr-only">${api().valueAsString}</span>
  <div
    ...api().getControlProps()
    data-slot="combobox-control"
    class="w-auto border-input relative flex items-center rounded-md border shadow-xs focus-within:border-ring focus-within:ring-[3px] focus-within:ring-ring/50"
  >
    <if=(input.multiple && api().hasSelectedItems)>
      <div data-slot="combobox-chips" class="bg-input/50 border-transparent focus-within:border-ring focus-within:ring-ring/30 has-aria-invalid:ring-destructive/20 dark:has-aria-invalid:ring-destructive/40 has-aria-invalid:border-destructive dark:has-aria-invalid:border-destructive/50 min-h-9 rounded-3xl border bg-clip-padding text-sm transition-[color,box-shadow,background-color] focus-within:ring-3 has-aria-invalid:ring-3 has-data-[slot=combobox-chip]:px-1.5 flex flex-wrap items-center gap-1 p-1">
        <for|item| of=api().selectedItems>
          <span data-slot="combobox-chip" class="bg-input text-foreground flex h-[calc(--spacing(5.5))] w-fit items-center justify-center gap-1 rounded-3xl px-2 text-xs font-medium whitespace-nowrap has-data-[slot=combobox-chip-remove]:pr-0 dark:bg-input/60 has-disabled:pointer-events-none has-disabled:cursor-not-allowed has-disabled:opacity-50">
            ${item.label}
            <button
              type="button"
              data-slot="combobox-chip-remove"
              class="-ml-1 opacity-50 hover:opacity-100"
              disabled=input.disabled
              on-click() { api().clearValue(item.value); }
            >
              <Icon name="X" class="pointer-events-none size-3"/>
            </button>
          </span>
        </for>
        <input
          ...api().getInputProps()
          data-slot="combobox-chip-input"
          class="min-w-16 flex-1 bg-transparent px-1 text-sm outline-none placeholder:text-muted-foreground disabled:cursor-not-allowed disabled:opacity-50"
        />
      </div>
    </if>
    <else>
      <input
        ...api().getInputProps()
        data-slot="combobox-input"
        class="h-9 flex-1 bg-transparent px-3 text-sm outline-none placeholder:text-muted-foreground disabled:cursor-not-allowed disabled:opacity-50"
      />
    </else>
    <if=(showClear && api().hasSelectedItems)>
      <button
        ...api().getClearTriggerProps()
        data-slot="combobox-clear"
        class="group-has-data-[slot=combobox-clear]/input-group:hidden data-pressed:bg-transparent flex h-9 w-9 items-center justify-center text-muted-foreground disabled:cursor-not-allowed disabled:opacity-50"
      >
        <Icon name="X" class="pointer-events-none size-4"/>
      </button>
    </if>
    <button
      ...api().getTriggerProps()
      data-slot="combobox-trigger"
      class="[&_svg:not([class*='size-'])]:size-4 flex h-9 w-9 items-center justify-center text-muted-foreground disabled:cursor-not-allowed disabled:opacity-50"
    >
      <Icon name="ChevronDown" class="text-muted-foreground pointer-events-none size-4 opacity-50"/>
    </button>
  </div>
  <portal>
    <if=api().open>
      <div ...api().getPositionerProps() style=positionerStyle data-slot="combobox-positioner" class="isolate z-50">
        <div
          ...api().getContentProps()
          data-slot="combobox-content"
          class="bg-popover text-popover-foreground data-open:animate-in data-closed:animate-out data-closed:fade-out-0 data-open:fade-in-0 data-closed:zoom-out-95 data-open:zoom-in-95 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 ring-foreground/5 dark:ring-foreground/10 *:data-[slot=input-group]:bg-input/50 *:data-[slot=input-group]:border-input/30 min-w-36 overflow-hidden rounded-3xl shadow-lg ring-1 duration-100 *:data-[slot=input-group]:m-1.5 *:data-[slot=input-group]:mb-0 *:data-[slot=input-group]:h-8 *:data-[slot=input-group]:shadow-none data-[side=inline-start]:slide-in-from-right-2 data-[side=inline-end]:slide-in-from-left-2 mu-menu-target mu-menu-translucent group/combobox-content relative max-h-(--available-height) w-(--reference-width) max-w-(--available-width) origin-(--transform-origin) overflow-x-hidden overflow-y-auto data-[state=open]:animate-in data-[state=open]:fade-in-0 data-[state=open]:zoom-in-95 data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=closed]:zoom-out-95"
        >
          <div ...api().getListProps() data-slot="combobox-list" class="no-scrollbar max-h-[min(calc(--spacing(72)---spacing(9)),calc(var(--available-height)---spacing(9)))] scroll-py-1.5 p-1.5 data-empty:p-0 overflow-y-auto overscroll-contain">
            <if=filteredGroups()>
              <for|group, groupIndex| of=filteredGroups()>
                <div data-slot="combobox-group" class="">
                  <div data-slot="combobox-label" class="text-muted-foreground px-3 py-2.5 text-xs">${group.label}</div>
                  <div data-slot="combobox-collection">
                    <for|item| of=group.items>
                      <div
                        ...api().getItemProps({ item })
                        data-slot="combobox-item"
                        class="data-highlighted:bg-accent data-highlighted:text-accent-foreground not-data-[variant=destructive]:data-highlighted:**:text-accent-foreground gap-2.5 rounded-2xl py-2 pr-8 pl-3 text-sm font-medium [&_svg:not([class*='size-'])]:size-4 relative flex w-full cursor-default items-center outline-hidden select-none data-[disabled]:pointer-events-none data-[disabled]:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0"
                      >
                        <span ...api().getItemTextProps({ item }) data-slot="combobox-item-text">${item.label}</span>
                        <span ...api().getItemIndicatorProps({ item }) data-slot="combobox-item-indicator" class="pointer-events-none absolute right-2 flex size-4 items-center justify-center">
                          <Icon name="Check" class="pointer-events-none size-4"/>
                        </span>
                      </div>
                    </for>
                  </div>
                </div>
                <if=(groupIndex < (filteredGroups()?.length ?? 0) - 1)>
                  <div data-slot="combobox-separator" class="bg-border -mx-1.5 my-1.5 h-px"></div>
                </if>
              </for>
            </if>
            <else>
              <div data-slot="combobox-collection">
                <for|item| of=filtered>
                  <div
                    ...api().getItemProps({ item })
                    data-slot="combobox-item"
                    class="relative flex w-full cursor-default items-center outline-hidden select-none data-[disabled]:pointer-events-none data-[disabled]:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0"
                  >
                    <span ...api().getItemTextProps({ item }) data-slot="combobox-item-text">${item.label}</span>
                    <span ...api().getItemIndicatorProps({ item }) data-slot="combobox-item-indicator" class="">
                      <Icon name="Check" class="pointer-events-none size-4"/>
                    </span>
                  </div>
                </for>
              </div>
            </else>
          </div>
          <if=(filtered.length === 0)>
            <div data-slot="combobox-empty" class="hidden w-full justify-center text-center group-data-empty/combobox-content:flex text-muted-foreground py-1.5 px-2 text-sm">No results found.</div>
          </if>
        </div>
      </div>
    </if>
  </portal>
</div>

<return=api>
